import{_ as t,H as i,f as a,i as E}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"加餐06｜客户生命周期管理：你的产品客户结构是怎样的？","description":"","frontmatter":{},"headers":[{"level":2,"title":"客户生命周期管理","slug":"客户生命周期管理","link":"#客户生命周期管理","children":[]},{"level":2,"title":"","slug":"","link":"#","children":[]},{"level":2,"title":"客户生命周期的应用","slug":"客户生命周期的应用","link":"#客户生命周期的应用","children":[]},{"level":2,"title":"基于留存用户分布特征的运营方法","slug":"基于留存用户分布特征的运营方法","link":"#基于留存用户分布特征的运营方法","children":[]}],"relativePath":"数据分析实战45讲/加餐06｜客户生命周期管理：你的产品客户结构是怎样的？.md","filePath":"数据分析实战45讲/加餐06｜客户生命周期管理：你的产品客户结构是怎样的？.md","lastUpdated":1779820717000}'),s={name:"数据分析实战45讲/加餐06｜客户生命周期管理：你的产品客户结构是怎样的？.md"};function n(r,e,o,p,l,g){return i(),a("div",null,[...e[0]||(e[0]=[E('<h1 id="加餐06-客户生命周期管理-你的产品客户结构是怎样的" tabindex="-1">加餐06｜客户生命周期管理：你的产品客户结构是怎样的？ <a class="header-anchor" href="#加餐06-客户生命周期管理-你的产品客户结构是怎样的" aria-label="Permalink to &quot;加餐06｜客户生命周期管理：你的产品客户结构是怎样的？&quot;">​</a></h1><p>你好，我是陈博士。</p><p>你是否注意到，不同品类的客户生命周期呈现出不同的特征？有些品类的客户容易持续购买，忠诚度高，而另一些品类的用户则表现出较高的流失率。如何通过分析品类间的用户结构差异，制定更有针对性的运营策略，以实现不同品类的用户增长和优化？</p><p>今天给你讲解客户生命周期管理（Customer Lifecycle Management，CLM），它可以更好地帮助品牌理解客户在不同生命周期阶段的需求、行为和价值。</p><h2 id="客户生命周期管理" tabindex="-1"><strong>客户生命周期管理</strong> <a class="header-anchor" href="#客户生命周期管理" aria-label="Permalink to &quot;**客户生命周期管理**&quot;">​</a></h2><p>生命周期是深挖用户的有效抓手，根据用户近期购买的行为表现，对比历史购买的趋势变化，将用户划分为：低潜期、高潜期、引入期、成长期、成熟期、衰退期、流失期。有了这些阶段的划分，我们就可以针对不同阶段用户特点，匹配不同的营销策略 ，最终提升运营的精准度和成功率。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E5%AE%9E%E6%88%9845%E8%AE%B2/images/839393/1a06eed5b927ac6e99c86d358654cfab.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E5%AE%9E%E6%88%9845%E8%AE%B2/images/839393/1a06eed5b927ac6e99c86d358654cfab.jpg" alt="图片"></a></p><p>这里我们可以将客户的生命周期划分为3大阶段或7小阶段。</p><p><strong>1. 获客阶段（潜在用户）</strong></p><ul><li><p>低潜期：品类潜在用户，平台站内发生过购买，没有品类相关行为。</p></li><li><p>高潜期：品类潜在用户，平台站内发生过购买，近期开始浏览品类。</p></li></ul><p><strong>2. 升值阶段（留存用户）</strong></p><ul><li><p>引入期：品类新用户，近期刚完成购买。</p></li><li><p>成长期：品类老用户，发生持续购买但没有到达稳定复购状态，趋势是越买越多。</p></li><li><p>成熟期：品类老用户，发生持续购买且到达稳定复购状态。</p></li><li><p>衰退期：品类老用户，发生持续购买，但没有处于稳定复购状态，趋势是越买越少。</p></li></ul><p><strong>3. 挽回阶段（挽留用户）</strong></p><ul><li>流失期：品类老用户，之前发生过购买，但近期都没有下单。</li></ul><p>有了阶段的定性描述，我们还需要对各个阶段进行定量计算，比如计算规则如下：</p><h2 id="" tabindex="-1"><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E5%AE%9E%E6%88%9845%E8%AE%B2/images/839393/09d542b0e95b678c9c1d70ea846fc58e.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E5%AE%9E%E6%88%9845%E8%AE%B2/images/839393/09d542b0e95b678c9c1d70ea846fc58e.jpg" alt="图片"></a> <a class="header-anchor" href="#" aria-label="Permalink to &quot;![图片](images/839393/09d542b0e95b678c9c1d70ea846fc58e.jpg)&quot;">​</a></h2><h2 id="客户生命周期的应用" tabindex="-1"><strong>客户生命周期的应用</strong> <a class="header-anchor" href="#客户生命周期的应用" aria-label="Permalink to &quot;**客户生命周期的应用**&quot;">​</a></h2><p>计算不是目的，应用才是我们的目标。</p><p>如何构建客户生命周期的运营方法论，我们可以观察品类中的用户结构都有哪些类型？</p><p>这里我们根据潜在用户、留存用户、流失用户在总用户中的比例，将品类的用户结构划分为3种类型（L型、U型、E型），并给出具体的计算方式。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E5%AE%9E%E6%88%9845%E8%AE%B2/images/839393/02745946f7fdb92260ed518e64909938.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E5%AE%9E%E6%88%9845%E8%AE%B2/images/839393/02745946f7fdb92260ed518e64909938.png" alt="图片"></a></p><p>每种用户结构类型都有它的特征，结合这些特征我们可以指定对应的运营策略。</p><p>这里我们按照计算规则，得出每个品类的用户结构类型，下面是结果示意：</p><p>L型：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E5%AE%9E%E6%88%9845%E8%AE%B2/images/839393/e1ebcdd589def73e1bd4ff6b3ddedbb7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E5%AE%9E%E6%88%9845%E8%AE%B2/images/839393/e1ebcdd589def73e1bd4ff6b3ddedbb7.png" alt="图片"></a></p><p>U型和E型：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E5%AE%9E%E6%88%9845%E8%AE%B2/images/839393/c9db5342ed1c0a0d6a0210b468babd48.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E5%AE%9E%E6%88%9845%E8%AE%B2/images/839393/c9db5342ed1c0a0d6a0210b468babd48.png" alt="图片"></a></p><p><strong>那么基于不同的用户结构，应该采用怎样的运营策略？</strong></p><ul><li><p><strong>针对 L 型：</strong> 因为大部分用户都在站外，同时站内用户的流失比例尚可，所以站内外拉新是品类用户运营的重点，即引到池子里来。</p></li><li><p><strong>针对 U 型：</strong> 虽然大部分用户在站外，但是站内来的用户流失比例较高（大于20%），因此流失挽回是品类用户运营的重点，攘外必须安内。</p></li><li><p><strong>针对 E 型：</strong> 大部分用户已经来到了池子里，同时很多用户都已不需要该产品了，因此存量用户的 ARPU 值提升了该品类用户运营的重点，目标是提升当前用户的价值变现。</p></li></ul><h2 id="基于留存用户分布特征的运营方法" tabindex="-1"><strong>基于留存用户分布特征的运营方法</strong> <a class="header-anchor" href="#基于留存用户分布特征的运营方法" aria-label="Permalink to &quot;**基于留存用户分布特征的运营方法**&quot;">​</a></h2><p>这里我们还可以针对关键的阶段——留存阶段，进行进一步的细分。</p><p>重点考虑 ARPU 指标，在快消品中，成熟期用户的ARPU值最高，是引入期、成长期、衰退期的3倍。</p><p>我们可以判断留存用户处于哪一个时期，分布是如何的，来计算不同的类型，执行对应的运营策略。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E5%AE%9E%E6%88%9845%E8%AE%B2/images/839393/e2e8a6768276473e60eb5a8d02736ab1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E5%AE%9E%E6%88%9845%E8%AE%B2/images/839393/e2e8a6768276473e60eb5a8d02736ab1.png" alt="图片"></a></p><p>L型品类：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E5%AE%9E%E6%88%9845%E8%AE%B2/images/839393/2856f351aa45d9bb1aac8bebf16f4498.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E5%AE%9E%E6%88%9845%E8%AE%B2/images/839393/2856f351aa45d9bb1aac8bebf16f4498.png" alt="图片"></a></p><p>U型和E型品类：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E5%AE%9E%E6%88%9845%E8%AE%B2/images/839393/f5097bf3d26957ce150cdab5f0ee7668.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E5%AE%9E%E6%88%9845%E8%AE%B2/images/839393/f5097bf3d26957ce150cdab5f0ee7668.png" alt="图片"></a></p><p><strong>那么基于留存用户的分布，应该采用怎样的运营策略？</strong></p><ul><li><p>引入期用户较多 → 重点关注新晋用户的二次购买。</p></li><li><p>引入期、成长期用户较多 → 提升整体用户的稳定复购。</p></li><li><p>引入期、衰退期用户较多 → 关注新晋用户的二次购买，同时避免高价值用户流失。</p></li><li><p>引入期、成长期、衰退期用户都较多 → 综合多种用户运营策略。</p></li></ul><p>通过对留存阶段的细分，我们可以得出以下的用户运营地图和重点运营人群。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E5%AE%9E%E6%88%9845%E8%AE%B2/images/839393/336547d9282ec5a4ee96285c902af06a.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E5%AE%9E%E6%88%9845%E8%AE%B2/images/839393/336547d9282ec5a4ee96285c902af06a.png" alt="图片"></a></p><p>好，这节课就到这里，期待你的转发，我们下节课再见！</p>',43)])])}const h=t(s,[["render",n]]);export{c as __pageData,h as default};
